\begin{itemize}\item[2.] The shaded region, \(R\), is bounded by the graph of \(y=x^{2}\) and the line \(y=4\), as shown in the figure above.
\begin{itemize}
\item[(a)] Find the area of \(R\).
\item[(b)] Find the volume of the solid generated by revolving \(R\) about the \(x\)-axis.
\item[(c)] There exists a number \(k, k>4\), such that when \(R\) is revolved about the line \(y=k\), the resulting solid has the same volume as the solid in part (b). Write, but do not solve, an equation involving an integral expression that can be used to find the value of \(k\).
\end{itemize}
\end{itemize}
![](https://cdn.mathpix.com/cropped/9af2a3d4-d37c-4829-9e6c-fdb3e50a6909-1.jpg?height=396&width=355&top_left_y=283&top_left_x=1489)
\begin{itemize}
\item[(a)]
\[
\begin{aligned}
\text { Area } & =\int_{-2}^{2}\left(4-x^{2}\right) d x \\
& =2 \int_{0}^{2}\left(4-x^{2}\right) d x \\
& =2\left[4 x-\frac{x^{3}}{3}\right]_{0}^{2} \\
& =\frac{32}{3}=10.666 \text { or } 10.667
\end{aligned}
\]
\end{itemize}
\[
\mathbf{2}\left\{\begin{array}{l}
1: \text { integral } \\
1: \text { answer }
\end{array}\right.
\]
\begin{itemize}
\item[(b)] Volume \(=\pi \int_{-2}^{2}\left(4^{2}-\left(x^{2}\right)^{2}\right) d x\)
\[
\begin{aligned}
& =2 \pi \int_{0}^{2}\left(16-x^{4}\right) d x \\
& =2 \pi\left[16 x-\frac{x^{5}}{5}\right]_{0}^{2} \\
& =\frac{256 \pi}{5}=160.849 \text { or } 160.850
\end{aligned}
\]
\end{itemize}
\[
\mathbf{3}\left\{\begin{array}{l}
\text { 1: limits and constant } \\
\text { 1: integrand } \\
1: \text { answer }
\end{array}\right.
\]
\begin{itemize}
\item[(c)] \(\pi \int_{-2}^{2}\left[\left(k-x^{2}\right)^{2}-(k-4)^{2}\right] d x=\frac{256 \pi}{5}\)
\end{itemize}
\[
4\left\{\begin{array}{l}
1: \text { limits and constant } \\
2: \text { integrand } \\
\quad<-1>\text { each error } \\
1: \text { equation }
